#include <stdio.h>

/* primeiroDivisor le N (sempre 2 ou mais) e imprime o MENOR numero, a partir
   de 2, que divide N sem deixar resto.
   O d nasce ANTES do for de proposito: depois do break, e ele que guarda a
   resposta que o printf mostra.
   A leitura e o printf ja estao escritos — falta o for com o break. */
void primeiroDivisor(void) {
    int n = 0;
    int d = 2;

    scanf("%d", &n);

    /* escreva aqui o for de d = 2 ate n que, quando n % d == 0, da break */

    printf("%d\n", d);
}

