/* teste do desafio primeiro-divisor — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o N que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen), captura o stdout no proprio teste e le
   a linha de volta. Os nomes dos arquivos temporarios sao POR CENARIO.
   Nunca ha fclose de stdin/stdout — so fflush — para o proximo freopen
   ficar legal (C11 7.21.4).
   Os tres N tem respostas diferentes (3, 13 e 7) e nenhum deles responde 2:
   um valor fixo no codigo reprova nos tres. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void primeiroDivisor(void);

SM_TEST(o_primeiro_divisor_de_quinze) {
    /* o 2 nao divide 15; o 3 divide, e o break sai com d valendo 3 */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "15\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    primeiroDivisor();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o primeiro divisor de 15", linha, "3\n",
              "o menor numero a partir de 2 que divide 15 sem resto e 3");
    /* a saida TERMINA na primeira linha — buffer NOVO com sentinel */
    char fim[80] = "(nada impresso)";
