#include <stdio.h>

void primeiroDivisor(void) {
    int n = 0;
    int d = 2;

    scanf("%d", &n);

    for (d = 2; d <= n; d++) {
        if (n % d == 0) {
            break;
        }
    }

    printf("%d\n", d);
}
